function rememberNodeOriginal(n){if(!n)return;const key=n.id;if(!pendingOriginalNodes.has(key))pendingOriginalNodes.set(key,deep(n))}
function rememberEdgeOriginal(e){if(!e)return;const key=e.id;if(!pendingOriginalEdges.has(key))pendingOriginalEdges.set(key,deep(e))}
function rememberStructuralOriginal(){if(!pendingStructuralSnapshot)pendingStructuralSnapshot=historyString()}
function buildPreEditSnapshot(){
  if(pendingStructuralSnapshot)return pendingStructuralSnapshot;
  if(!pendingOriginalNodes.size&&!pendingOriginalEdges.size)return null;
  const snap=deep(project);snap.snapshots=[];
  for(const pg of snap.pages||[]){
    pg.nodes=(pg.nodes||[]).map(n=>pendingOriginalNodes.has(n.id)?deep(pendingOriginalNodes.get(n.id)):n);
    pg.edges=(pg.edges||[]).map(e=>pendingOriginalEdges.has(e.id)?deep(pendingOriginalEdges.get(e.id)):e);
  }
  return JSON.stringify(snap)
}

let pendingUISig='';function pendingCanvasUI(){const b=$('#pendingCanvasBadge'),btn=$('#refreshCanvasBtn');const n=pendingItems.size,sig=(pendingCanvasChanges?'1':'0')+':'+n;if(sig===pendingUISig)return;pendingUISig=sig;if(b){b.textContent=pendingCanvasChanges?`待更新 ${n||'多'} 項`:'畫布已同步';b.classList.toggle('dirty',pendingCanvasChanges)}if(btn){btn.classList.toggle('sync-dirty',pendingCanvasChanges);btn.disabled=!pendingCanvasChanges}}
function beginDeferredEdit(keys=[],pages=[]){pendingCanvasChanges=true;for(const k of keys)if(k)pendingItems.add(k);for(const p of pages)if(p)pendingPages.add(typeof p==='string'?p:p.id);pendingCanvasUI()}
