function applyTheme(){project.settings=project.settings||{displayMode:'light',displayFields:[],nodeContentCollapsed:false,nodeStyle:'presentation'};project.settings.displayFields??=[];project.settings.nodeContentCollapsed??=false;project.settings.nodeStyle??='presentation';const dark=project.settings.displayMode==='launchDark';document.body.classList.toggle('launch-dark',dark);const r=document.documentElement.style;r.setProperty('--accent',dark?'#6EA8FE':'#4472C4');r.setProperty('--accent-50',dark?'#142033':'#eef4ff');r.setProperty('--accent-100',dark?'#1c2e49':'#dce8fb');r.setProperty('--accent-700',dark?'#9CC2FF':'#2F5597');r.setProperty('--node-radius',(project.globalStyles?.radius??12)+'px');r.setProperty('--node-padding',(project.globalStyles?.padding??12)+'px');r.setProperty('--edge-width',(project.globalStyles?.edge??2)+'px');const dm=$('#displayModeSelect');if(dm)dm.value=project.settings.displayMode||'light';const ns=$('#nodeStyleSelect');if(ns)ns.value=project.settings.nodeStyle||'presentation';const hint=$('#nodeContentStateHint');if(hint)hint.textContent='目前：'+(project.settings.nodeContentCollapsed?'全部摺疊':'全部展開')}
function deletePage(pageId){if(project.pages.length<=1){toast('至少要保留一個分頁');return}const pg=project.pages.find(p=>p.id===pageId);if(!pg)return;if(!confirm(`確定刪除分頁「${pg.name}」？\n此分頁內的節點與連接線會一起刪除。`))return;flushBeforeDirectCanvasAction();pushHistory();const idx=project.pages.findIndex(p=>p.id===pageId);project.pages.splice(idx,1);if(project.activePageId===pageId){project.activePageId=project.pages[Math.max(0,Math.min(idx,project.pages.length-1))].id}selected.clear();selectedEdge=null;selectedEdges.clear();invalidateRoutes();renderAll();saveLocal();toast('已刪除分頁')}
function renderTabs(){const el=$('#tabs');el.innerHTML='';project.pages.forEach(p=>{const wrap=document.createElement('div');wrap.className='tabitem'+(p.id===project.activePageId?' active':'');const b=document.createElement('button');b.className='tab'+(p.id===project.activePageId?' active':'');b.textContent=p.name;b.title='雙擊重新命名';b.ondblclick=()=>{const n=prompt('分頁名稱',p.name);if(n){pushHistory();p.name=n;renderTabs();saveLocal()}};b.onclick=()=>{if(p.id===project.activePageId)return;flushBeforeDirectCanvasAction();project.activePageId=p.id;selected.clear();selectedEdge=null;selectedEdges.clear();renderAll();saveLocal()};const x=document.createElement('button');x.className='tab-close';x.textContent='×';x.title='刪除分頁';x.disabled=project.pages.length<=1;x.onclick=e=>{e.stopPropagation();deletePage(p.id)};wrap.appendChild(b);wrap.appendChild(x);el.appendChild(wrap)});const a=document.createElement('button');a.className='tabadd';a.textContent='＋';a.title='新增分頁';a.onclick=()=>{flushBeforeDirectCanvasAction();pushHistory();const p={id:uid(),name:'Page '+(project.pages.length+1),nodes:[],edges:[],lanes:[],timeline:[],roadConfig:{laneField:'Category',timeField:'Year',sortField:'',autoSync:true,laneHeight:190,timeCellWidth:300}};project.pages.push(p);project.activePageId=p.id;selected.clear();selectedEdge=null;selectedEdges.clear();renderAll();saveLocal()};el.appendChild(a)}
