 p.roadConfig??={laneField:'Category',timeField:'Year',autoSync:true,laneHeight:190,timeCellWidth:300};
 p.roadConfig.laneField??='Category';p.roadConfig.timeField??='Year';p.roadConfig.sortField??='';p.roadConfig.autoSync??=true;p.roadConfig.laneHeight??=190;p.roadConfig.timeCellWidth??=300;p.roadConfig.laneOrderByField??={};
