function dimensionValue(n,key,fallback){const v=n.fields?.[key];return v===undefined||v===null||String(v).trim()===''?fallback:String(v).trim()}
function syncRoadmapDimensions(reposition=false){const p=page();ensurePageV2(p);const cfg=p.roadConfig;
 const laneValues=orderedLaneValues(p,new Set(p.nodes.map(n=>dimensionValue(n,cfg.laneField,'未分類'))));
 const timeValues=smartSortValues(new Set(p.nodes.map(n=>dimensionValue(n,cfg.timeField,'未排程'))));
 const oldLane=new Map((p.lanes||[]).map(l=>[l.name,l]));
 const maxW=Math.max(180,...p.nodes.map(n=>n.w||180));cfg.timeCellWidth=Math.max(cfg.timeCellWidth||300,maxW+56);const cellW=cfg.timeCellWidth,baseH=cfg.laneHeight||190;
 const byCell=new Map();for(const n of p.nodes){const lv=dimensionValue(n,cfg.laneField,'未分類'),tv=dimensionValue(n,cfg.timeField,'未排程'),k=lv+'\u0000'+tv;if(!byCell.has(k))byCell.set(k,[]);byCell.get(k).push(n)}
 let y=60;p.lanes=laneValues.map(name=>{let stack=0;for(const t of timeValues){const arr=byCell.get(name+'\u0000'+t)||[];const h=arr.reduce((z,n)=>z+(nodeRenderHeight(n)),0)+Math.max(0,arr.length-1)*18;stack=Math.max(stack,h)}const old=oldLane.get(name),computed=Math.max(baseH,70+stack+20);const h=reposition?computed:Math.max(computed,old?.h||0);const l={id:old?.id||uid(),name,y,h,collapsed:old?.collapsed||false};y+=l.collapsed?36:h;return l});p.timeline=timeValues;
 const laneByName=new Map(p.lanes.map(l=>[l.name,l])),timeIndex=new Map(p.timeline.map((t,i)=>[t,i]));if(reposition){const offsets=new Map();for(const n of p.nodes){const lv=dimensionValue(n,cfg.laneField,'未分類'),tv=dimensionValue(n,cfg.timeField,'未排程'),l=laneByName.get(lv);n.laneId=l?.id||null;if(!l)continue;const k=lv+'\u0000'+tv,off=offsets.get(k)||0;n.x=150+(timeIndex.get(tv)||0)*cellW+Math.max(20,(cellW-n.w)/2);n.y=l.y+52+off;offsets.set(k,off+(nodeRenderHeight(n))+18)}}else for(const n of p.nodes){const lv=dimensionValue(n,cfg.laneField,'未分類');n.laneId=laneByName.get(lv)?.id||null}
 return {lanes:laneValues,times:timeValues};
}
function renderRoadmapControls(){const p=page();ensurePageV2(p);const names=fieldNames(p),lane=$('#laneFieldSelect'),time=$('#timeFieldSelect'),sort=$('#sortFieldSelect');if(!lane||!time)return;const opts=names.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');lane.innerHTML=opts;time.innerHTML=opts;lane.value=p.roadConfig.laneField;time.value=p.roadConfig.timeField;if(sort){sort.innerHTML='<option value="">依關係自動排序</option>'+opts;sort.value=p.roadConfig.sortField||''}$('#autoSyncToggle').checked=!!p.roadConfig.autoSync;const orderEl=$('#laneOrderList');if(orderEl){const vals=orderedLaneValues(p,new Set(p.nodes.map(n=>dimensionValue(n,p.roadConfig.laneField,'未分類'))));orderEl.innerHTML=vals.length?vals.map((v,i)=>`<div class="lane-order-row"><span title="${esc(v)}">${esc(v)}</span><div><button class="lane-order-btn" data-lane-up="${esc(v)}" ${i===0?'disabled':''}>↑</button><button class="lane-order-btn" data-lane-down="${esc(v)}" ${i===vals.length-1?'disabled':''}>↓</button></div></div>`).join(''):'<div class="hint">目前沒有泳道值</div>';document.querySelectorAll('[data-lane-up]').forEach(b=>b.onclick=()=>moveLaneOrder(b.dataset.laneUp,-1));document.querySelectorAll('[data-lane-down]').forEach(b=>b.onclick=()=>moveLaneOrder(b.dataset.laneDown,1));const reset=$('#resetLaneOrderBtn');if(reset)reset.onclick=resetLaneOrder}renderDisplayFields()}

