function renderDisplayFields(){const el=$('#displayFields');if(!el)return;const names=fieldNames(page()),stored=project.settings?.displayFields||[],valid=stored.filter(k=>names.includes(k)),chosen=new Set(valid.length?valid:names);el.innerHTML=names.length?names.map(k=>`<label><input type="checkbox" data-display-field="${esc(k)}" ${chosen.has(k)?'checked':''}>${esc(k)}</label>`).join(''):'<div class="hint">建立自訂欄位後可在這裡選擇。</div>';$$('[data-display-field]').forEach(cb=>cb.onchange=()=>{project.settings.displayFields=$$('[data-display-field]:checked').map(x=>x.dataset.displayField);renderNodes();saveLocal()})}
function effectiveNodeStyle(n){const color=n.color||DEFAULT_NODE_COLOR,dark=project.settings?.displayMode==='launchDark',style=project.settings?.nodeStyle||'presentation';let bg=dark?'#141B24':'#FFFFFF',border=dark?blendHex('#334354',color,.18):'#D7DEE8',title=dark?'#F7FAFC':'#172033';if(style==='outline'){bg=dark?'#0F1722':'#FFFFFF';border=dark?blendHex(color,'#ffffff',.18):color}if(style==='soft'){bg=dark?blendHex('#141B24',color,.16):blendHex('#ffffff',color,.12);border=dark?blendHex(color,'#ffffff',.15):blendHex('#D7DEE8',color,.38)}if(style==='header')border=dark?blendHex('#334354',color,.24):blendHex('#D7DEE8',color,.18);return {style,color,bg,border,title,meta:dark?'#D2DCE7':'#526071',label:dark?'#9FB0C3':'#667085',value:dark?'#ECF2F8':'#344054'} }
function paletteHTML(attr,color){return Object.entries(officePalettes).map(([name,colors])=>`<div class="palette-row-label">${({red:'紅',orange:'橘',green:'綠',blue:'藍',purple:'紫',gray:'灰'})[name]}</div><div class="palette-grid">${colors.map(c=>`<button class="swatch ${String(color||'').toUpperCase()===c.toUpperCase()?'active':''}" ${attr}="${c}" style="background:${c}" title="${name}"></button>`).join('')}</div>`).join('')}

