function renderLanes(){lanesLayer.innerHTML='';const p=page();ensurePageV2(p);syncRoadmapDimensions(false);const cfg=p.roadConfig,cellW=cfg.timeCellWidth||300;const band=document.createElement('div');band.className='timeline-band';band.style.width=Math.max(5850,p.timeline.length*cellW+400)+'px';p.timeline.forEach((t,i)=>{const c=document.createElement('div');c.className='timecell';c.style.left=(i*cellW)+'px';c.style.width=cellW+'px';c.textContent=t;band.appendChild(c);const g=document.createElement('div');g.className='timegrid';g.style.left=(150+i*cellW)+'px';lanesLayer.appendChild(g)});lanesLayer.appendChild(band);const pill=document.createElement('div');pill.className='mapping-pill';pill.textContent=`泳道：${cfg.laneField} · 時間：${cfg.timeField}`;lanesLayer.appendChild(pill);p.lanes.forEach(l=>{const d=document.createElement('div');d.className='lane'+(l.collapsed?' collapsed':'');d.style.top=l.y+'px';d.style.height=l.h+'px';d.dataset.id=l.id;const h=document.createElement('div');h.className='lane-head';h.innerHTML=`${l.collapsed?'▶':'▼'} ${esc(l.name)}<small>${esc(cfg.laneField)}</small>`;h.style.pointerEvents='auto';h.style.cursor='pointer';h.onclick=()=>{pushHistory();l.collapsed=!l.collapsed;syncRoadmapDimensions(false);renderAll();saveLocal()};d.appendChild(h);lanesLayer.appendChild(d)})}
function nodeVisible(n){let cur=n;const seen=new Set();while(cur?.parentId&&!seen.has(cur.parentId)){seen.add(cur.parentId);const par=page().nodes.find(x=>x.id===cur.parentId);if(par?.collapsed)return false;cur=par}const lane=page().lanes.find(l=>l.id===n.laneId);if(lane?.collapsed)return false;return true}
function hexToRgb(hex){let h=String(hex||'').replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');const n=parseInt(h,16);return Number.isFinite(n)?[(n>>16)&255,(n>>8)&255,n&255]:[29,78,216]}
function hexToRgba(hex,a=.1,fallback='#fff'){const [r,g,b]=hexToRgb(hex);return `rgba(${r},${g},${b},${a})`}
function darkenHex(hex,amt=.25){const [r,g,b]=hexToRgb(hex),f=1-amt;return `rgb(${Math.round(r*f)},${Math.round(g*f)},${Math.round(b*f)})`}
function blendHex(a,b,t){a=(a||'#64748b').replace('#','');b=(b||'#ffffff').replace('#','');if(a.length===3)a=a.split('').map(x=>x+x).join('');if(b.length===3)b=b.split('').map(x=>x+x).join('');const A=[0,2,4].map(i=>parseInt(a.slice(i,i+2),16)),B=[0,2,4].map(i=>parseInt(b.slice(i,i+2),16));return '#'+A.map((v,i)=>Math.round(v+(B[i]-v)*t).toString(16).padStart(2,'0')).join('')}
function effectiveEdgeColor(e){const c=e.color||DEFAULT_EDGE_COLOR;return project.settings?.displayMode==='launchDark'?blendHex(c,'#ffffff',.32):c}

function nodeContentCollapsed(n){return project.settings?.nodeContentCollapsed===true}
function visibleFieldEntries(n){if(nodeContentCollapsed(n))return [];const keys=effectiveDisplayFields();return keys.map(k=>[k,n.fields?.[k]]).filter(([,v])=>v!==undefined&&v!==null&&String(v).trim()!=='')}
function normalizedNodeTitle(n){return String(n?.title??'').replace(/\\n/g,'\n')}
function nodeTitleLineCount(n){const style=project.settings?.nodeStyle||'presentation',font=style==='compact'?13:15,pad=(project.globalStyles?.padding??12)*2+24,usable=Math.max(70,(n.w||180)-pad),chars=Math.max(6,Math.floor(usable/(font*.57)));let lines=0;for(const raw of normalizedNodeTitle(n).split('\n')){const txt=raw||' ';lines+=Math.max(1,Math.ceil([...txt].length/chars))}return Math.max(1,lines)}
