function nodeMinExpandedHeight(n){const style=project.settings?.nodeStyle||'presentation', rows=visibleFieldEntries(n).length,titleExtra=Math.max(0,nodeTitleBlockHeight(n)-(style==='compact'?16:19));if(!rows)return (style==='compact'?64:76)+titleExtra;const base=style==='header'?66:(style==='compact'?50:58), step=style==='compact'?14:18;return base+titleExtra+rows*step+12}
