function canvasViewportBounds(buffer=420){const w=vp.clientWidth||1200,h=vp.clientHeight||800;return {x1:(-pan.x)/zoom-buffer,y1:(-pan.y)/zoom-buffer,x2:(w-pan.x)/zoom+buffer,y2:(h-pan.y)/zoom+buffer}}
function nodeInRenderViewport(n,buffer=420){if(selected.has(n.id))return true;const b=canvasViewportBounds(buffer),h=nodeRenderHeight(n);return n.x+n.w>=b.x1&&n.x<=b.x2&&n.y+h>=b.y1&&n.y<=b.y2}
function edgeMayBeInRenderViewport(e,buffer=620){const a=page().nodes.find(n=>n.id===e.source),b=page().nodes.find(n=>n.id===e.target);if(!a||!b)return false;const v=canvasViewportBounds(buffer),ah=nodeRenderHeight(a),bh=nodeRenderHeight(b);const x1=Math.min(a.x,b.x),x2=Math.max(a.x+a.w,b.x+b.w),y1=Math.min(a.y,b.y),y2=Math.max(a.y+ah,b.y+bh);return x2>=v.x1&&x1<=v.x2&&y2>=v.y1&&y1<=v.y2}
