 if(q.sx===q.tx)add([{x:q.sx,y:q.sy},{x:q.tx,y:q.ty}]);
 // One clean elbow when possible.
 add([{x:q.sx,y:q.sy},{x:q.tx,y:q.sy},{x:q.tx,y:q.ty}]);
