function smartEdgePath(e){const key=page().id+'|'+e.id+'|'+routeEpoch,cached=edgeRouteCache.get(key);if(cached)return cached;const q=edgePoints(e);if(!q)return null;const pts=aestheticRoute(q)||routeCandidates(q)||[{x:q.sx,y:q.sy},{x:(q.sx+q.tx)/2,y:q.sy},{x:(q.sx+q.tx)/2,y:q.ty},{x:q.tx,y:q.ty}];let d=roundedOrthogonalPath(pts,18);let bestLen=-1,lx=(q.sx+q.tx)/2,ly=(q.sy+q.ty)/2;for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1],len=Math.abs(a.x-b.x)+Math.abs(a.y-b.y);if(len>bestLen){bestLen=len;lx=(a.x+b.x)/2;ly=(a.y+b.y)/2}}const r={d,lx,ly,points:pts};edgeRouteCache.set(key,r);return r}
