 for(let li=0;li<p.lanes.length;li++){const lane=p.lanes[li],ln=byLane.get(li)||[];if(cfg.sortField){const values=smartSortValues(new Set(ln.map(n=>layoutFieldValue(n,cfg.sortField)||'（空白）')));let rowY=lane.y+topPad;for(const v of values){const row=ln.filter(n=>(layoutFieldValue(n,cfg.sortField)||'（空白）')===v),groups=new Map();for(const n of row){const ti=timeIndex.get(String(dimensionValue(n,cfg.timeField,'未排程')))??0;if(!groups.has(ti))groups.set(ti,[]);groups.get(ti).push(n)}let band=72;for(const arr of groups.values()){arr.sort((a,b)=>{const da=p.edges.filter(e=>e.source===a.id||e.target===a.id).length,db=p.edges.filter(e=>e.source===b.id||e.target===b.id).length;return db-da||a.title.localeCompare(b.title,'zh-Hant')});let cy=rowY;for(const n of arr){const ti=timeIndex.get(String(dimensionValue(n,cfg.timeField,'未排程')))??0;n.x=150+ti*cellW+Math.max(20,(cellW-n.w)/2);n.y=cy;cy+=(nodeRenderHeight(n))+gap}band=Math.max(band,cy-rowY-gap)}rowY+=band+rowGap}}else{const groups=new Map();for(const n of ln){const ti=timeIndex.get(String(dimensionValue(n,cfg.timeField,'未排程')))??0;if(!groups.has(ti))groups.set(ti,[]);groups.get(ti).push(n)}for(const [ti,arr] of groups){arr.sort((a,b)=>{const da=p.edges.filter(e=>e.source===a.id||e.target===a.id).length,db=p.edges.filter(e=>e.source===b.id||e.target===b.id).length;return db-da||a.title.localeCompare(b.title,'zh-Hant')});let cy=lane.y+topPad;for(const n of arr){n.x=150+ti*cellW+Math.max(20,(cellW-n.w)/2);n.y=cy;cy+=(nodeRenderHeight(n))+gap}}}}
