function addLane(){const p=page();ensurePageV2(p);const field=p.roadConfig.laneField;const value=prompt(`新增「${field}」泳道值`,'New Lane');if(!value)return;pushHistory();let targets=p.nodes.filter(n=>selected.has(n.id));if(!targets.length){const _id=uid();const n={id:_id,title:'New Node',description:'',x:220,y:120,w:180,h:96,laneId:null,parentId:null,color:DEFAULT_NODE_COLOR,fields:{[field]:value,[p.roadConfig.timeField]:p.timeline[0]||String(new Date().getFullYear())}};p.nodes.push(n);targets=[n];selected=new Set([n.id])}else targets.forEach(n=>{n.fields??={};n.fields[field]=value});syncRoadmapDimensions(true);renderAll();saveLocal()}
