function batchColor(){if(!selected.size){toast('尚未選擇節點');return}const c=$('#batchColor').value;if(!c){toast('請先選擇節點色彩');return}pushHistory();page().nodes.filter(n=>selected.has(n.id)).forEach(n=>{n.color=c});renderAll();saveLocal()}

