function canvasWrapLines(ctx,text,maxWidth){const out=[];for(const para of String(text??'').replace(/\\n/g,'\n').split('\n')){if(!para){out.push('');continue}let line='';for(const ch of [...para]){const test=line+ch;if(line&&ctx.measureText(test).width>maxWidth){out.push(line);line=ch}else line=test}if(line||!out.length)out.push(line)}return out}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
async function exportHTML(){
  try {
    const response = await fetch('./standalone-template.html', { cache: 'no-store' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    let html = await response.text();
    const data = JSON.stringify(project).replace(/<\/script/gi, '<\\/script');
    html = html.replace(
      /<script id="initialData" type="application\/json">[\s\S]*?<\/script>/,
      `<script id="initialData" type="application/json">${data}<\/script>`,
    );
    download((project.name||'roadmap')+'-standalone.html',new Blob([html],{type:'text/html'}));
    toast('已匯出單一 HTML');
  } catch (error) {
    console.error(error);
    toast('HTML 匯出失敗：找不到 standalone template');
  }
}
