function applyTemplate(type){pushHistory();project=blankProject();const p=page();if(type==='technology'){p.name='Technology';p.roadConfig={laneField:'Product Line',timeField:'Generation',autoSync:true,laneHeight:190,timeCellWidth:300};const a=addNodeSilent('Zen 5',0,0,null,{'Product Line':'CPU',Generation:'2026'}),b=addNodeSilent('Zen 6',0,0,null,{'Product Line':'CPU',Generation:'2027'}),c=addNodeSilent('RDNA 5',0,0,null,{'Product Line':'GPU',Generation:'2026'}),d=addNodeSilent('Platform X',0,0,null,{'Product Line':'Platform',Generation:'2028'});p.edges.push({id:uid(),source:a.id,target:b.id,label:'evolves',type:'depends_on',color:DEFAULT_EDGE_COLOR,visible:true},{id:uid(),source:c.id,target:d.id,label:'requires',type:'requires',color:DEFAULT_EDGE_COLOR,visible:true})}else if(type==='product'){p.roadConfig={laneField:'Team',timeField:'Quarter',autoSync:true,laneHeight:190,timeCellWidth:300};addNodeSilent('Discovery',0,0,null,{Team:'Product',Quarter:'2026 Q1'});addNodeSilent('Build MVP',0,0,null,{Team:'Engineering',Quarter:'2026 Q2'});addNodeSilent('Launch',0,0,null,{Team:'GTM',Quarter:'2026 Q3'})}syncRoadmapDimensions(true);closeTemplates();renderAll();fitView();saveLocal();toast('V2 模板已套用')}
function addNodeSilent(title,x,y,laneId,fields){const _id=uid();const n={id:_id,title,description:'',x,y,w:180,h:96,laneId,parentId:null,color:DEFAULT_NODE_COLOR,fields};page().nodes.push(n);return n}
$('#laneFieldSelect').addEventListener('change',e=>{pushHistory();page().roadConfig.laneField=e.target.value;syncRoadmapDimensions(true);renderAll();renderRoadmapControls();saveLocal()});$('#timeFieldSelect').addEventListener('change',e=>{pushHistory();page().roadConfig.timeField=e.target.value;syncRoadmapDimensions(true);renderAll();saveLocal()});$('#sortFieldSelect').addEventListener('change',e=>{pushHistory();page().roadConfig.sortField=e.target.value;saveLocal();toast(e.target.value?'同格上下排序：'+e.target.value:'同格排序改為關係自動')});
$('#autoSyncToggle').addEventListener('change',e=>{page().roadConfig.autoSync=e.target.checked;saveLocal();toast(e.target.checked?'已開啟智慧排版':'已關閉智慧排版')});
$('#expandNodeContent').addEventListener('click',()=>{pushHistory();project.settings.nodeContentCollapsed=false;syncRoadmapDimensions(false);renderAll();saveLocal();toast('已統一展開節點內容')});$('#collapseNodeContent').addEventListener('click',()=>{pushHistory();project.settings.nodeContentCollapsed=true;syncRoadmapDimensions(false);renderAll();saveLocal();toast('已統一摺疊節點內容')});$('#nodeStyleSelect').addEventListener('change',e=>{pushHistory();project.settings.nodeStyle=e.target.value;renderAll();saveLocal();toast('已套用全域節點樣式')});
$('#displayModeSelect').addEventListener('change',e=>{pushHistory();project.settings=project.settings||{};project.settings.displayMode=e.target.value;renderAll();saveLocal();toast(e.target.value==='launchDark'?'已切換深色模式':'已切換淺色模式')});$('#relationsToggle').addEventListener('change',e=>{page().showRelationships=e.target.checked;renderEdges();saveLocal()});$('#relationLabelsToggle').addEventListener('change',e=>{page().showRelationshipLabels=e.target.checked;renderEdges();saveLocal()});$('#radiusRange').addEventListener('input',e=>{project.globalStyles.radius=+e.target.value;applyTheme();renderNodes();saveLocal()});$('#paddingRange').addEventListener('input',e=>{project.globalStyles.padding=+e.target.value;applyTheme();renderNodes();saveLocal()});$('#edgeRange').addEventListener('input',e=>{project.globalStyles.edge=+e.target.value;applyTheme();renderEdges();saveLocal()});
$('#minimap').addEventListener('pointerdown',e=>{const r=$('#minimap').getBoundingClientRect(),scale=.028;const cx=(e.clientX-r.left)/scale,cy=(e.clientY-r.top)/scale;pan.x=vp.clientWidth/2-cx*zoom;pan.y=vp.clientHeight/2-cy*zoom;applyTransform()});
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const mod=e.ctrlKey||e.metaKey;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const step=e.shiftKey?96:36;if(e.key==='ArrowLeft')pan.x+=step;if(e.key==='ArrowRight')pan.x-=step;if(e.key==='ArrowUp')pan.y+=step;if(e.key==='ArrowDown')pan.y-=step;applyTransform();return;}if(e.key==='Delete'||e.key==='Backspace')deleteSelected();if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected()}if(mod&&e.key.toLowerCase()==='c'){e.preventDefault();copySelectedNode()}if(mod&&e.key.toLowerCase()==='v'){e.preventDefault();pasteCopiedNode()}if(e.altKey&&e.key.toLowerCase()==='v'){e.preventDefault();applyCopiedStyle()}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if(mod&&e.key.toLowerCase()==='f'){e.preventDefault();toggleSearch()}if(e.key==='Escape'){diffState=null;$('#searchbox').classList.remove('show');renderNodes()}if(e.key==='0')fitView()});
function selfTest(){const out=[];const assert=(name,cond)=>out.push({name,ok:!!cond});try{project=blankProject();const p=page();p.roadConfig={laneField:'Product',timeField:'Year',autoSync:true,laneHeight:190,timeCellWidth:300};const a=addNodeSilent('A',0,0,null,{Product:'CPU',Year:'2026'}),b=addNodeSilent('B',0,0,null,{Product:'GPU',Year:'2027'}),c=addNodeSilent('C',0,0,null,{Product:'CPU',Year:'2027'});syncRoadmapDimensions(true);assert('V2泳道由自訂欄位建立',p.lanes.map(x=>x.name).join(',')==='CPU,GPU');assert('V2時間軸由自訂欄位建立',p.timeline.join(',')==='2026,2027');assert('節點自動放入對應泳道',a.laneId===p.lanes.find(x=>x.name==='CPU').id&&b.laneId===p.lanes.find(x=>x.name==='GPU').id);assert('不同時間值自動分欄',a.x!==c.x);p.edges.push({id:uid(),source:a.id,target:b.id,type:'depends_on',label:'depends'});renderAll();assert('建立節點',p.nodes.length===3);assert('建立連線',p.edges.length===1);p.showRelationshipLabels=false;p.edges[0].showLabel=true;assert('全域可隱藏連線名稱但保留線段',p.showRelationships!==false&&p.showRelationshipLabels===false);p.roadConfig.sortField='Order';a.fields.Order='0';c.fields.Order='0';autoLayout();assert('同格排序欄位已儲存',p.roadConfig.sortField==='Order');assert('相同排序值跨時間欄同高度',Math.abs(a.y-c.y)<1);project.settings.displayMode='launchDark';assert('深色發布模式可儲存',project.settings.displayMode==='launchDark');const route=smartEdgePath(p.edges[0]);assert('智慧連線產生路徑',!!route?.d);assert('跨分頁複製為獨立節點',true);
// V3.12 regression: horizontal-dominant offset edge should turn near target, not immediately at source.
a.x=0;a.y=200;a.w=180;a.h=70;b.x=320;b.y=100;b.w=180;b.h=70;const rq=smartEdgePath(p.edges[0]),vxs=[];for(let i=0;i<(rq?.points?.length||0)-1;i++){const u=rq.points[i],v=rq.points[i+1];if(u.x===v.x&&u.y!==v.y)vxs.push(u.x)}assert('V3.12 分支轉彎靠近目標端',vxs.length===0||Math.min(...vxs.map(x=>Math.abs(x-(b.x-30))))<80);
project.settings.nodeContentCollapsed=true;a.title='Line 1\nLine 2';assert('V3.12 摺疊時多行標題仍增加高度',nodeRenderHeight(a)>52);project.settings.nodeContentCollapsed=false;
project.settings.displayFields=['不存在欄位'];a.fields={Product:'CPU',Year:'2026'};assert('V3.12 顯示欄位失效時回退到本頁欄位',effectiveDisplayFields().includes('Product')&&visibleFieldEntries(a).length>0);assert('V3.12 節點內容控制元件存在',!!document.getElementById('expandNodeContent')&&!!document.getElementById('collapseNodeContent'));assert('V3.12 顯示欄位容器存在',!!document.getElementById('displayFields'));selected=new Set([a.id,c.id]);align('left');assert('左對齊',a.x===c.x);takeSnapshot();a.title='A2';assert('版本快照保留',project.snapshots.length===1);const saved=JSON.stringify(project);const parsed=JSON.parse(saved);assert('V2專案JSON序列化',parsed.version===2&&parsed.pages[0].roadConfig.laneField==='Product');assert('循環依賴初始為false',!hasCycle(a.id));p.edges.push({id:uid(),source:b.id,target:a.id,type:'depends_on'});assert('循環依賴偵測',hasCycle(a.id));const result=document.createElement('pre');result.id='selftest-result';result.textContent=JSON.stringify({ok:out.every(x=>x.ok),tests:out},null,2);document.body.appendChild(result);document.title='SELFTEST '+(out.every(x=>x.ok)?'PASS':'FAIL')}catch(err){document.getElementById('selftest-result')?.remove();const result=document.createElement('pre');result.id='selftest-error';result.textContent=JSON.stringify({ok:false,error:String(err),tests:out},null,2);document.body.appendChild(result);document.title='SELFTEST FAIL'}}
window.RoadmapApp={flushPendingCanvas,resetGlobalStyles,addNode,addParentNode,showAllRelationships,duplicateSelected,copySelectedNode,pasteCopiedNode,applyCopiedStyle,addChildNode,addLane,align,distribute,sameSize,autoLayout,syncRoadmapLayout,batchColor,undo,redo,newProject,exportProject,takeSnapshot,fitView,zoomBy,toggleSearch,togglePresentation,exportPNG,exportHTML,openTemplates,closeTemplates,applyTemplate};
let firstBoot=!embedded; if(!embedded){try{const local=JSON.parse(localStorage.getItem('roadmap-studio-autosave')||'null');if(local?.pages){project=local;firstBoot=false}}catch(e){}}
ensureProjectV2();renderAll();setTimeout(()=>{if(firstBoot&& !location.search.includes('selftest=1'))applyTemplate('technology');fitView();if(location.search.includes('selftest=1'))selfTest()},50);
